-- Local-only additive peer tutoring. Migrations001-004 are immutable.
CREATE TABLE public.peer_tutor_profiles(id TEXT PRIMARY KEY,owner TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,programme TEXT NOT NULL,academic_level TEXT NOT NULL,introduction TEXT NOT NULL,visible INTEGER NOT NULL,available INTEGER NOT NULL,profile_version TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE public.peer_tutor_courses(id TEXT PRIMARY KEY,tutor_id TEXT NOT NULL REFERENCES public.peer_tutor_profiles(id),course_code TEXT NOT NULL,UNIQUE(tutor_id,course_code));
CREATE TABLE public.peer_tutor_requests(id TEXT PRIMARY KEY,requester TEXT NOT NULL,tutor_id TEXT NOT NULL REFERENCES public.peer_tutor_profiles(id),course_code TEXT NOT NULL,requester_name TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL,operation_id TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,updated_at TEXT NOT NULL,contact_method TEXT,contact_value TEXT,consented_at TEXT,revoked_at TEXT,UNIQUE(requester,operation_id),CHECK(status IN ('pending','accepted','declined','cancelled','expired')));
CREATE UNIQUE INDEX peer_one_pending ON peer_tutor_requests(requester,course_code) WHERE status='pending';
CREATE INDEX peer_course_search ON peer_tutor_courses(course_code,tutor_id);
CREATE INDEX peer_requests_tutor ON peer_tutor_requests(tutor_id,status);
CREATE TABLE public.peer_tutor_events(id TEXT PRIMARY KEY,request_id TEXT NOT NULL REFERENCES public.peer_tutor_requests(id),recipient TEXT NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT,UNIQUE(request_id,recipient,kind));
CREATE INDEX peer_event_recipient ON peer_tutor_events(recipient,created_at);
ALTER TABLE public.peer_tutor_profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.peer_tutor_profiles FROM PUBLIC,anon,authenticated,unilus_backend;
GRANT SELECT,INSERT,UPDATE ON public.peer_tutor_profiles TO unilus_backend;
CREATE POLICY peer_select ON public.peer_tutor_profiles FOR SELECT TO unilus_backend USING(true);
CREATE POLICY peer_insert ON public.peer_tutor_profiles FOR INSERT TO unilus_backend WITH CHECK(true);
CREATE POLICY peer_update ON public.peer_tutor_profiles FOR UPDATE TO unilus_backend USING(true) WITH CHECK(true);
ALTER TABLE public.peer_tutor_courses ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.peer_tutor_courses FROM PUBLIC,anon,authenticated,unilus_backend;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.peer_tutor_courses TO unilus_backend;
CREATE POLICY peer_select ON public.peer_tutor_courses FOR SELECT TO unilus_backend USING(true);
CREATE POLICY peer_insert ON public.peer_tutor_courses FOR INSERT TO unilus_backend WITH CHECK(true);
CREATE POLICY peer_update ON public.peer_tutor_courses FOR UPDATE TO unilus_backend USING(true) WITH CHECK(true);
CREATE POLICY peer_delete ON public.peer_tutor_courses FOR DELETE TO unilus_backend USING(true);
ALTER TABLE public.peer_tutor_requests ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.peer_tutor_requests FROM PUBLIC,anon,authenticated,unilus_backend;
GRANT SELECT,INSERT,UPDATE ON public.peer_tutor_requests TO unilus_backend;
CREATE POLICY peer_select ON public.peer_tutor_requests FOR SELECT TO unilus_backend USING(true);
CREATE POLICY peer_insert ON public.peer_tutor_requests FOR INSERT TO unilus_backend WITH CHECK(true);
CREATE POLICY peer_update ON public.peer_tutor_requests FOR UPDATE TO unilus_backend USING(true) WITH CHECK(true);
ALTER TABLE public.peer_tutor_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.peer_tutor_events FROM PUBLIC,anon,authenticated,unilus_backend;
GRANT SELECT,INSERT,UPDATE ON public.peer_tutor_events TO unilus_backend;
CREATE POLICY peer_select ON public.peer_tutor_events FOR SELECT TO unilus_backend USING(true);
CREATE POLICY peer_insert ON public.peer_tutor_events FOR INSERT TO unilus_backend WITH CHECK(true);
CREATE POLICY peer_update ON public.peer_tutor_events FOR UPDATE TO unilus_backend USING(true) WITH CHECK(true);
